package com.astarworks.astera.core.domain.effect

/** Glyph heights (font pixels) of the solid and the patterned overlays. */
public const val SOLID_OVERLAY_HEIGHT: Int = 1024
public const val PATTERN_OVERLAY_HEIGHT: Int = 384

/**
 * Full-screen cut-in overlays for `screen_flash`. Each one is a single glyph of the
 * `astera:overlay` bitmap font (generated by `:tools:resource-pack`, `OverlayArtGenerator`)
 * shown as a TITLE: the glyph is so large it covers the screen, the title colour tints it
 * and the title fade_in / stay / fade_out ticks fade it.
 *
 * Sizing (the numbers `OverlayArtGenerator` bakes into the font): a title is drawn at
 * 4x GUI scale, so one font pixel = 4 GUI pixels; a glyph of height H spans 4*H GUI pixels.
 * [SOLID_OVERLAY_HEIGHT] 1024 -> 4096 GUI px, covers every aspect ratio / GUI scale >= 1 on 4K.
 * [PATTERN_OVERLAY_HEIGHT] 384 -> 1536 GUI px, covers 1080p at scale >= 1 and 4K at scale >= 3
 * (16:9 .. 21:9); at smaller GUI scales the pattern is cropped to its centre.
 */
public enum class ScreenOverlay(
    /** Value in YAML (`overlay: gold_burst`). */
    public val yamlName: String,
    /** The glyph (private use area) in the `astera:overlay` font. */
    public val glyph: Char,
    /** Tint when the mechanic gives no `color`. */
    public val defaultColor: Int,
    /** Glyph height in font pixels (see class doc). */
    public val height: Int,
) {
    WHITE("white", '', 0xFFFFFF, SOLID_OVERLAY_HEIGHT),
    VIGNETTE("vignette", '', 0x000000, PATTERN_OVERLAY_HEIGHT),
    GOLD_BURST("gold_burst", '', 0xFFC84A, PATTERN_OVERLAY_HEIGHT),
    SPEED_DIAG("speed_diag", '', 0xFFFFFF, PATTERN_OVERLAY_HEIGHT),
    SPEED_RADIAL("speed_radial", '', 0xFFFFFF, PATTERN_OVERLAY_HEIGHT),
    IMPACT_STAR("impact_star", '', 0xFFFFFF, PATTERN_OVERLAY_HEIGHT),
    ;

    public companion object {
        public const val FONT_NAMESPACE: String = "astera"
        public const val FONT_PATH: String = "overlay"

        /**
         * Ascent that centres a glyph of [height] on the screen centre: the title text line is drawn
         * at y = -10 with a 7-unit baseline, so the glyph top sits at -3 - ascent; top = -height/2.
         */
        public fun ascentFor(height: Int): Int = height / 2 - 3

        public fun fromYaml(name: String): ScreenOverlay? = entries.firstOrNull { it.yamlName == name }
    }
}
